from pathlib import Path

ROOT = Path.cwd()
T = ROOT / 'app' / 'templates'
S = ROOT / 'app' / 'static'
T.mkdir(parents=True, exist_ok=True)
S.mkdir(parents=True, exist_ok=True)

JS = r'''const ClassicAccessTree=(()=>{
 const esc=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML};
 const norm=v=>String(v||'').trim().toLocaleLowerCase('pt-BR');
 const statusClass=v=>norm(v)==='permitido'?'allowed':norm(v)==='negado'?'denied':'unknown';
 const parts=v=>String(v||'Sem caminho').split(/\s*>\s*|\s*\/\s*|\s*\\\s*/).map(x=>x.trim()).filter(Boolean);
 function makeRoot(){return{children:new Map(),screens:new Map()}}
 function build(items){const root=makeRoot();for(const item of items){let node=root;for(const p of parts(item.caminho)){if(!node.children.has(p))node.children.set(p,makeRoot());node=node.children.get(p)}const screen=item.tela||'Sem tela';if(!node.screens.has(screen))node.screens.set(screen,[]);node.screens.get(screen).push(item)}return root}
 function icon(status){const c=statusClass(status);return `<span class="classic-access-icon ${c}">${c==='allowed'?'✓':c==='denied'?'✕':'•'}</span>`}
 function badge(status){return `<span class="classic-badge ${statusClass(status)}">${esc(status||'Nao identificado')}</span>`}
 function accessLine(item,compare=false){const line=document.createElement('div');line.className=`classic-access-line ${statusClass(item.status)}`;line.dataset.search=`${item.caminho} ${item.tela} ${item.botao} ${item.statusA||''} ${item.statusB||''}`.toLocaleLowerCase('pt-BR');line.innerHTML=`${icon(item.status)}<span class="classic-access-name">${esc(item.botao||'Sem botao')}</span><span class="classic-access-status">${compare?badge(item.statusA)+'<span class="status-arrow">→</span>'+badge(item.statusB):badge(item.status)}</span>`;return line}
 function screenLine(name,items,select){const wrap=document.createElement('div');wrap.className='classic-screen-wrap';const btn=document.createElement('button');btn.type='button';btn.className='classic-screen-line';btn.dataset.search=`${name} ${items.map(i=>i.botao).join(' ')}`.toLocaleLowerCase('pt-BR');btn.innerHTML=`<span class="screen-check">✓</span><span>${esc(name)}</span><small>${items.length}</small>`;btn.onclick=()=>select(name,items,btn);wrap.appendChild(btn);return wrap}
 function branch(name,node,select,depth=0){const details=document.createElement('details');details.className='classic-branch';details.open=depth===0;const summary=document.createElement('summary');summary.dataset.search=name.toLocaleLowerCase('pt-BR');summary.innerHTML=`<span class="classic-expander"></span><span class="classic-folder"></span><span class="classic-label">${esc(name)}</span>`;details.appendChild(summary);const children=document.createElement('div');children.className='classic-children';[...node.children.entries()].sort(([a],[b])=>a.localeCompare(b,'pt-BR')).forEach(([child,value])=>children.appendChild(branch(child,value,select,depth+1)));[...node.screens.entries()].sort(([a],[b])=>a.localeCompare(b,'pt-BR')).forEach(([screen,items])=>children.appendChild(screenLine(screen,items,select)));details.appendChild(children);return details}
 function pathLine(item,compare=false){const row=document.createElement('div');row.className='classic-path-row';row.dataset.search=`${item.caminho} ${item.tela} ${item.botao}`.toLocaleLowerCase('pt-BR');row.innerHTML=`<div>${icon(item.status)}<span>${esc(item.caminho)} <b>›</b> ${esc(item.tela)} <b>›</b> ${esc(item.botao)}</span></div><div>${compare?badge(item.statusA)+'<span class="status-arrow">→</span>'+badge(item.statusB):badge(item.status)}</div>`;return row}
 function mount(root){const source=document.getElementById(root.dataset.source);if(!source)return;const items=JSON.parse(source.textContent||'[]');const compare=root.dataset.compare==='true';const tree=root.querySelector('[data-classic-tree]');const access=root.querySelector('[data-classic-accesses]');const title=root.querySelector('[data-classic-title]');const paths=root.querySelector('[data-classic-paths]');const select=(screen,list,button)=>{root.querySelectorAll('.classic-screen-line.active').forEach(x=>x.classList.remove('active'));button.classList.add('active');title.textContent=screen;access.innerHTML='';list.sort((a,b)=>String(a.botao).localeCompare(String(b.botao),'pt-BR')).forEach(i=>access.appendChild(accessLine(i,compare)))};const h=build(items);tree.innerHTML='';[...h.children.entries()].sort(([a],[b])=>a.localeCompare(b,'pt-BR')).forEach(([name,node])=>tree.appendChild(branch(name,node,select)));[...h.screens.entries()].forEach(([screen,list])=>tree.appendChild(screenLine(screen,list,select)));access.innerHTML='<p class="classic-empty">Selecione uma tela na arvore.</p>';paths.innerHTML='';items.slice().sort((a,b)=>(a.caminho+a.tela+a.botao).localeCompare(b.caminho+b.tela+b.botao,'pt-BR')).forEach(i=>paths.appendChild(pathLine(i,compare)));root.querySelectorAll('[data-classic-mode]').forEach(btn=>btn.onclick=()=>{root.dataset.mode=btn.dataset.classicMode;root.querySelectorAll('[data-classic-mode]').forEach(x=>x.classList.toggle('active',x===btn))});const search=root.querySelector('[data-classic-search]');search.oninput=()=>{const q=norm(search.value);root.querySelectorAll('[data-search]').forEach(x=>x.hidden=q&&!x.dataset.search.includes(q));root.querySelectorAll('details').forEach(d=>{const visible=[...d.querySelectorAll('.classic-screen-line')].some(x=>!x.hidden);d.hidden=!visible;if(q&&visible)d.open=true})}}
 function comparison(root){const source=document.getElementById(root.dataset.compareSource);if(!source)return;const sets=JSON.parse(source.textContent||'{}');const all=[...(sets.manter||[]),...(sets.adicionar||[]),...(sets.remover||[])];const body=root.querySelector('[data-compare-body]');const pathsPanel=root.querySelector('[data-compare-paths]');body.innerHTML='';pathsPanel.innerHTML='';const h=build(all);function compareBranch(name,node,depth=0){const details=document.createElement('details');details.className='classic-branch compare-branch';details.open=depth===0;details.innerHTML=`<summary><span class="classic-expander"></span><span class="classic-folder"></span><span class="classic-label">${esc(name)}</span></summary>`;const children=document.createElement('div');children.className='classic-children';[...node.children.entries()].sort(([a],[b])=>a.localeCompare(b,'pt-BR')).forEach(([n,v])=>children.appendChild(compareBranch(n,v,depth+1)));[...node.screens.entries()].sort(([a],[b])=>a.localeCompare(b,'pt-BR')).forEach(([screen,items])=>{const screenBlock=document.createElement('div');screenBlock.className='compare-screen';screenBlock.innerHTML=`<div class="compare-screen-title">${esc(screen)}</div>`;items.sort((a,b)=>String(a.botao).localeCompare(String(b.botao),'pt-BR')).forEach(i=>{const r=document.createElement('div');r.className='compare-access-row';r.dataset.search=`${i.caminho} ${i.tela} ${i.botao}`.toLocaleLowerCase('pt-BR');r.innerHTML=`<div>${icon(i.statusA)}<span>${esc(i.botao)}</span>${badge(i.statusA)}</div><div>${icon(i.statusB)}<span>${esc(i.botao)}</span>${badge(i.statusB)}</div>`;screenBlock.appendChild(r)});children.appendChild(screenBlock)});details.appendChild(children);return details}[...h.children.entries()].sort(([a],[b])=>a.localeCompare(b,'pt-BR')).forEach(([n,v])=>body.appendChild(compareBranch(n,v)));all.forEach(i=>pathsPanel.appendChild(pathLine(i,true)));root.querySelectorAll('[data-compare-mode]').forEach(btn=>btn.onclick=()=>{root.dataset.mode=btn.dataset.compareMode;root.querySelectorAll('[data-compare-mode]').forEach(x=>x.classList.toggle('active',x===btn))});const search=root.querySelector('[data-compare-search]');search.oninput=()=>{const q=norm(search.value);root.querySelectorAll('[data-search]').forEach(x=>x.hidden=q&&!x.dataset.search.includes(q));root.querySelectorAll('details').forEach(d=>{const visible=[...d.querySelectorAll('.compare-access-row')].some(x=>!x.hidden);d.hidden=!visible;if(q&&visible)d.open=true})}}
 return{start(){document.querySelectorAll('[data-classic-browser]').forEach(mount);document.querySelectorAll('[data-profile-tab]').forEach(btn=>btn.onclick=()=>{const group=btn.closest('[data-profile-tabs]');group.querySelectorAll('[data-profile-tab]').forEach(x=>x.classList.toggle('active',x===btn));document.querySelectorAll(`[data-profile-panel="${group.dataset.profileTabs}"]`).forEach(x=>x.classList.toggle('active',x.id===btn.dataset.profileTab))});document.querySelectorAll('[data-classic-comparison]').forEach(comparison)}}})();document.addEventListener('DOMContentLoaded',ClassicAccessTree.start);
'''
(S/'classic-tree.js').write_text(JS,encoding='utf-8',newline='\n')

CSS=r'''.classic-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:10px 0}.classic-modes{display:flex;gap:5px}.classic-modes button,.profile-tabs button{border:1px solid #bac5cf;background:#f6f7f8;color:#243447;border-radius:4px;padding:7px 11px;cursor:pointer}.classic-modes button.active,.profile-tabs button.active{background:#dbeafe;border-color:#7ca8d4;color:#12375f}.classic-search{width:min(420px,100%);padding:7px 9px;border:1px solid #aebdca;border-radius:4px}.classic-browser{border:1px solid #cfd6dc;background:#fff}.classic-browser-grid{display:grid;grid-template-columns:minmax(440px,1.35fr) minmax(300px,.85fr);min-height:560px}.classic-menu-pane{border-right:1px solid #cfd6dc}.classic-pane-title{height:30px;padding:6px 9px;border-bottom:1px solid #cfd6dc;background:#fafafa;font-size:13px;font-weight:700}.classic-tree,.classic-accesses{height:560px;overflow:auto;padding:8px 10px;font-size:13px}.classic-branch{margin:0}.classic-branch summary{list-style:none;display:flex;align-items:center;gap:4px;min-height:22px;cursor:pointer;white-space:nowrap}.classic-branch summary::-webkit-details-marker{display:none}.classic-expander:before{content:'+';display:grid;place-items:center;width:11px;height:11px;border:1px solid #777;background:#fff;font-size:9px;line-height:9px}.classic-branch[open]>summary .classic-expander:before{content:'−'}.classic-folder:before{content:'📁';font-size:15px}.classic-branch[open]>summary .classic-folder:before{content:'📂'}.classic-children{margin-left:5px;padding-left:14px;border-left:1px dotted #8d99a5}.classic-screen-line{display:grid;grid-template-columns:18px minmax(120px,1fr) auto;align-items:center;gap:3px;width:100%;min-height:22px;padding:1px 4px;border:0;background:transparent;text-align:left;cursor:pointer;font-size:13px}.classic-screen-line:hover,.classic-screen-line.active{background:#dbeafe}.screen-check{color:#0aaa37;font-size:18px;font-weight:900}.classic-screen-line small{color:#7b8794}.classic-access-line{display:grid;grid-template-columns:20px minmax(130px,1fr) auto;align-items:center;gap:4px;min-height:27px;border-bottom:1px solid #f0f1f2}.classic-access-icon{font-size:18px;font-weight:900}.classic-access-icon.allowed{color:#0aaa37}.classic-access-icon.denied{color:#d92d20}.classic-access-icon.unknown{color:#7b8794}.classic-access-status,.right-badges{display:flex;align-items:center;gap:5px}.classic-badge{padding:2px 7px;border-radius:999px;font-size:11px;font-weight:700}.classic-badge.allowed{color:#067124;background:#d9fbe3}.classic-badge.denied{color:#9b1913;background:#ffe0dd}.classic-badge.unknown{color:#5e6975;background:#e9edf0}.classic-empty{color:#77828c}.classic-paths{display:none;max-height:620px;overflow:auto;padding:8px}.classic-browser[data-mode="paths"] .classic-browser-grid{display:none}.classic-browser[data-mode="paths"] .classic-paths{display:block}.classic-path-row{display:grid;grid-template-columns:minmax(320px,1fr) auto;gap:8px;align-items:center;padding:7px 8px;border-bottom:1px solid #e7eaed}.classic-path-row>div{display:flex;align-items:center;gap:5px}.classic-path-row b{color:#7a8794}.profile-tabs{display:flex;gap:5px;flex-wrap:wrap;margin:10px 0}.profile-panel{display:none}.profile-panel.active{display:block}.consolidated-rule{padding:8px 10px;border-left:4px solid #0aaa37;background:#effff4;margin:8px 0}.classic-comparison{border:1px solid #cfd6dc;background:#fff}.compare-header{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid #cfd6dc}.compare-header>div{padding:8px 10px;background:#fafafa;font-weight:700}.compare-header>div:first-child{border-right:1px solid #cfd6dc}.compare-tree{padding:8px 10px;max-height:660px;overflow:auto}.compare-screen{margin:2px 0 5px 0}.compare-screen-title{padding:3px 4px;color:#183b5e;font-weight:700}.compare-access-row{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid #eef0f2}.compare-access-row>div{display:grid;grid-template-columns:20px minmax(80px,1fr) auto;align-items:center;gap:4px;padding:4px 8px}.compare-access-row>div:first-child{border-right:1px solid #d8dde2}.compare-paths{display:none;padding:8px;max-height:660px;overflow:auto}.classic-comparison[data-mode="paths"] .compare-tree{display:none}.classic-comparison[data-mode="paths"] .compare-paths{display:block}.status-arrow{color:#7b8794}@media(max-width:950px){.classic-browser-grid{grid-template-columns:1fr}.classic-menu-pane{border-right:0;border-bottom:1px solid #cfd6dc}.classic-tree,.classic-accesses{height:auto;max-height:480px}.classic-toolbar{align-items:stretch;flex-direction:column}.classic-search{width:100%}.compare-access-row{grid-template-columns:1fr}.compare-access-row>div:first-child{border-right:0;border-bottom:1px dashed #d8dde2}.classic-path-row{grid-template-columns:1fr}}
'''
# append so existing shell remains
styles=S/'styles.css'
old=styles.read_text(encoding='utf-8') if styles.exists() else ''
styles.write_text(old+'\n'+CSS,encoding='utf-8',newline='\n')

BASE=T/'base.html'
base=BASE.read_text(encoding='utf-8') if BASE.exists() else '<!doctype html><html><body><main>{% block content %}{% endblock %}</main></body></html>'
# remove prior visual script references, retain only new one
for pattern in ["<script src=\"{{ url_for('static',path='/access-browser.js') }}\"></script>","<script src=\"{{ url_for('static', path='/tree.js') }}\"></script>","<script src=\"{{ url_for('static',path='/tree.js') }}\"></script>"]:
    base=base.replace(pattern,'')
if "classic-tree.js" not in base:
    base=base.replace('</body>',"<script src=\"{{ url_for('static',path='/classic-tree.js') }}\"></script></body>")
BASE.write_text(base,encoding='utf-8',newline='\n')

PARTIAL='''<div class="classic-toolbar"><div class="classic-modes"><button class="active" data-classic-mode="tree">Arvore de acessos</button><button data-classic-mode="paths">Somente caminhos</button></div><input class="classic-search" data-classic-search placeholder="Pesquisar caminho, tela ou botao"></div><div class="classic-browser" data-classic-browser data-source="{{ source_id }}" data-mode="tree" data-compare="{{ 'true' if compare else 'false' }}"><div class="classic-browser-grid"><section class="classic-menu-pane"><div class="classic-pane-title">Opcoes do Menu</div><div class="classic-tree" data-classic-tree></div></section><section><div class="classic-pane-title" data-classic-title>Acessos</div><div class="classic-accesses" data-classic-accesses></div></section></div><div class="classic-paths" data-classic-paths></div></div>'''
(T/'_classic_access.html').write_text(PARTIAL,encoding='utf-8',newline='\n')

FUNC='''{% extends "base.html" %}{% block title %}{{ funcionario.nome }}{% endblock %}{% block content %}<a class="back" href="/estrutura">Voltar para usuarios</a><section class="hero compact"><p class="eyebrow">Usuario</p><h1>{{ funcionario.nome }}</h1><p>{{ funcionario.login }} | {{ funcionario.departamento.nome if funcionario.departamento else 'Departamento nao definido' }}</p></section><div class="profile-tabs" data-profile-tabs="userProfiles"><button class="active" data-profile-tab="consolidado">Consolidado</button>{% for item in por_perfil %}<button data-profile-tab="perfil-{{ item.perfil.id }}">{{ item.perfil.nome }}</button>{% endfor %}</div><section id="consolidado" class="profile-panel active" data-profile-panel="userProfiles"><div class="consolidated-rule">Se qualquer perfil permitir, o resultado consolidado será <b>Permitido</b>.</div><script type="application/json" id="classic-consolidado">{{ consolidado|tojson }}</script>{% set source_id='classic-consolidado' %}{% set compare=false %}{% include '_classic_access.html' %}</section>{% for item in por_perfil %}<section id="perfil-{{ item.perfil.id }}" class="profile-panel" data-profile-panel="userProfiles"><script type="application/json" id="classic-perfil-{{ item.perfil.id }}">{{ item.acessos|tojson }}</script>{% set source_id='classic-perfil-' ~ item.perfil.id %}{% set compare=false %}{% include '_classic_access.html' %}</section>{% endfor %}{% endblock %}'''
(T/'funcionario.html').write_text(FUNC,encoding='utf-8',newline='\n')

PROFILE='''{% extends "base.html" %}{% block title %}{{ perfil.nome }}{% endblock %}{% block content %}<a class="back" href="/perfis">Voltar para perfis</a><section class="hero compact"><p class="eyebrow">Perfil</p><h1>{{ perfil.nome }}</h1><p>{{ usuarios|length }} usuarios vinculados</p></section><script type="application/json" id="classic-profile">{{ acessos|tojson }}</script>{% set source_id='classic-profile' %}{% set compare=false %}{% include '_classic_access.html' %}{% endblock %}'''
(T/'perfil.html').write_text(PROFILE,encoding='utf-8',newline='\n')

COMPARE='''{% extends "base.html" %}{% block title %}Comparar perfis{% endblock %}{% block content %}<section class="hero"><p class="eyebrow">Comparativo</p><h1>Comparar dois perfis</h1><p>As duas permissões aparecem em colunas alinhadas pelo mesmo caminho, tela e botão.</p></section><form class="compare-form" method="get"><select name="perfil_a" required><option value="">Perfil A</option>{% for p in perfis %}<option value="{{ p.id }}" {% if perfil_a and p.id==perfil_a.id %}selected{% endif %}>{{ p.nome }}</option>{% endfor %}</select><select name="perfil_b" required><option value="">Perfil B</option>{% for p in perfis %}<option value="{{ p.id }}" {% if perfil_b and p.id==perfil_b.id %}selected{% endif %}>{{ p.nome }}</option>{% endfor %}</select><input name="busca" value="{{ busca }}" placeholder="Pesquisar"><button>Comparar</button></form>{% if resultado %}<script type="application/json" id="classic-comparison-data">{{ resultado|tojson }}</script><div class="classic-toolbar"><div class="classic-modes"><button class="active" data-compare-mode="tree">Arvores alinhadas</button><button data-compare-mode="paths">Somente caminhos</button></div><input class="classic-search" data-compare-search placeholder="Pesquisar caminho, tela ou botao"></div><div class="classic-comparison" data-classic-comparison data-compare-source="classic-comparison-data" data-mode="tree"><div class="compare-header"><div>{{ perfil_a.nome }}</div><div>{{ perfil_b.nome }}</div></div><div class="compare-tree" data-compare-body></div><div class="compare-paths" data-compare-paths></div></div>{% endif %}{% endblock %}'''
(T/'comparar.html').write_text(COMPARE,encoding='utf-8',newline='\n')

print('Arvore classica e comparacao lado a lado configuradas.')
print('Reinicie o Uvicorn e atualize o navegador com Ctrl+F5.')
